def load_config_file() -> Dict[str, Any]:
    """Load Jest configuration from multiple possible sources with priority."""
    # Priority 1: jest.config.js (CommonJS)
    config_path = Path(CONFIG_FILE)
    if config_path.exists():
        try:
            # Use Node.js to evaluate the config file safely
            result = subprocess.run(
                ["node", "-e", f"console.log(JSON.stringify(require('./{CONFIG_FILE}')))"],
                capture_output=True,
                text=True,
                check=True,
                cwd=Path.cwd(),
            )
            return json.loads(result.stdout)
        except (subprocess.CalledProcessError, json.JSONDecodeError) as e:
            pytest.fail(f"Failed to parse {CONFIG_FILE}: {e}")

    # Priority 2: jest.config.json
    json_path = Path(CONFIG_JSON_FILE)
    if json_path.exists():
        try:
            with open(json_path, "r", encoding="utf-8") as f:
                return json.load(f)
        except (json.JSONDecodeError, OSError) as e:
            pytest.fail(f"Failed to parse {CONFIG_JSON_FILE}: {e}")

    # Priority 3: package.json "jest" key
    pkg_path = Path(PACKAGE_JSON_FILE)
    if pkg_path.exists():
        try:
            with open(pkg_path, "r", encoding="utf-8") as f:
                pkg_data = json.load(f)
            if "jest" in pkg_data:
                return pkg_data["jest"]
        except (json.JSONDecodeError, OSError) as e:
            pytest.fail(f"Failed to parse {PACKAGE_JSON_FILE}: {e}")

    pytest.skip("No Jest configuration file found (tried jest.config.js, jest.config.json, package.json)")


def validate_glob_pattern(pattern: str) -> bool:
    """Validate that a glob pattern is syntactically correct."""
    if not isinstance(pattern, str) or not pattern.strip():
        return False
    if not VALID_GLOB_PATTERN.match(pattern):
        return False
    # Check for balanced brackets
    if pattern.count("[") != pattern.count("]"):
        return False
    if pattern.count("(") != pattern.count(")"):
        return False
    if pattern.count("{") != pattern.count("}"):
        return False
    return True


def validate_module_path(path: str) -> bool:
    """Validate that a module path is syntactically correct."""
    if not isinstance(path, str) or not path.strip():
        return False
    return bool(VALID_MODULE_PATH.match(path))


def validate_threshold(value: Union[int, float]) -> bool:
    """Validate that a coverage threshold is within acceptable range."""
    if not isinstance(value, (int, float)):
        return False
    if isinstance(value, bool):
        return False
    return VALID_THRESHOLD_RANGE[0] <= value <= VALID_THRESHOLD_RANGE[1]


def check_mock_files_exist() -> Dict[str, bool]:
    """Check if required mock files exist."""
    base_dir = Path.cwd()
    mock_files = {
        "styleMock": base_dir / "tests" / "__mocks__" / "styleMock.js",
        "fileMock": base_dir / "tests" / "__mocks__" / "fileMock.js",
        "setupTests": base_dir / "tests" / "setupTests.js",
    }
    return {name: path.exists() for name, path in mock_files.items()}


